export function FaviconMark({ url, size }: { url: string; size: number }): React.ReactElement {
  const [src, setSrc] = useState<string | null>(null)
  useEffect(() => {
    let live = true
    void getFavicon(url).then((path) => {
      if (live && path) setSrc(window.api.mediaUrl(path))
    })
    return () => {
      live = false
    }
  }, [url])
  if (!src) return <KeyRound size={size} aria-hidden />
  return <img src={src} width={size} height={size} alt="" aria-hidden />
}

export function KeyProviderIcon({
  provider,
  size = 18
}: {
  provider: string
  size?: number
}): React.ReactElement {
  const mark = MARKS[provider]
  if (!mark) {
    const docsUrl = keyProvider(provider)?.docsUrl
    if (docsUrl) return <FaviconMark url={docsUrl} size={size} />
    return <KeyRound size={size} aria-hidden />
  }
  const fill = mark.hex === '#000000' ? 'currentColor' : mark.hex
  return (
    <svg viewBox="0 0 24 24" width={size} height={size} aria-hidden>
      <path fill={fill} d={mark.d} />
    </svg>
  )
}
